import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"SuperKernel","link":"/guide/programming_guide/advanced_programming/super_kernel/principles"},{"text":"算子自验证说明","link":"/guide/programming_guide/advanced_programming/super_kernel/operator_self_verification"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/super_kernel/operator_self_verification.md","filePath":"guide/programming_guide/advanced_programming/super_kernel/operator_self_verification.md","outlineHeaders":[{"level":2,"title":"验证思路","slug":"验证思路","link":"#验证思路"},{"level":2,"title":"npugraph_ex后端验证样例","slug":"npugraph_ex后端验证样例","link":"#npugraph_ex后端验证样例"},{"level":3,"title":"示例代码","slug":"示例代码","link":"#示例代码"},{"level":3,"title":"关键点说明","slug":"关键点说明","link":"#关键点说明"},{"level":2,"title":"GE图模式验证样例","slug":"GE图模式验证样例","link":"#GE图模式验证样例"},{"level":3,"title":"示例代码","slug":"示例代码-1","link":"#示例代码-1"},{"level":3,"title":"关键点说明","slug":"关键点说明-1","link":"#关键点说明-1"},{"level":2,"title":"多算子融合验证","slug":"多算子融合验证","link":"#多算子融合验证"}],"lastUpdated":1786949923000}'),l={name:"guide/programming_guide/advanced_programming/super_kernel/operator_self_verification.md"};function e(o,s,t,r,_,i){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>算子自验证说明</h1><p>本文档面向Ascend C算子开发者，提供单算子融合进SuperKernel的验证样例。算子开发完成后，可通过本文档中的样例自行验证算子是否支持融合进SuperKernel，包括功能正确性与精度对齐。</p><p>当前SuperKernel特性有两种开启方式：npugraph_ex后端和GE图模式，两种方式在前端开启方式上有所不同。开发者通常只需选择其中一种进行验证；如需在两种方式下均验证算子兼容性，可以分别参考下文样例。</p><h2 id="验证思路">验证思路<a class="header-anchor" href="#验证思路">​</a></h2><p>通用的单算子自验证思路如下：</p><ol><li><strong>构造一个仅包含待验证算子的<code>torch.nn.Module</code></strong>：构造一个原始版本（不开启SuperKernel）和一个SuperKernel版本（在算子调用处标定SuperKernel范围）。</li><li><strong>分别用图模式编译并执行两个模型</strong>：原始版本作为基准，SuperKernel版本作为目标。</li><li><strong>比对两个版本的输出</strong>：若数值完全相等（或在可接受误差范围内），则证明算子在SuperKernel下功能与精度正确。</li><li><strong>补充多算子联合验证</strong>：单算子验证能够排查大部分SuperKernel适配问题，是验证流程中必要且高效的第一步。但部分问题（如Cache一致性导致的精度差异）在单算子场景下通常不会暴露，需要在多个算子融合后的实际模型中才会显现。因此，单算子验证通过后，建议进一步构建多算子联合用例或在实际模型中验证，以确保算子在整网SuperKernel场景下的兼容性。</li></ol><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>SuperKernel范围内即使只包含一个算子，也会按SuperKernel路径进行编译和执行，可以充分检验算子是否支持SuperKernel融合。如需验证多个算子的融合效果，排查融合后对其他算子的影响，可以将待验证算子与其他Ascend C算子一起放入SuperKernel范围内。</p></div><h2 id="npugraph_ex后端验证样例">npugraph_ex后端验证样例<a class="header-anchor" href="#npugraph_ex后端验证样例">​</a></h2><p>npugraph_ex后端开启SuperKernel融合时，编译后端需使用<code>&quot;npugraph_ex&quot;</code>，并在<code>options</code>中显式传入<code>super_kernel_optimize=True</code>。如需控制融合范围，可通过<code>torch.npu.super_kernel_scope_begin</code>/<code>torch.npu.super_kernel_scope_end</code>一对接口进行标定。</p><h3 id="示例代码">示例代码<a class="header-anchor" href="#示例代码">​</a></h3><p>以下示例以<code>torch_npu.npu_moe_gating_top_k_softmax</code>为例，演示在npugraph_ex后端下的SuperKernel单算子验证：</p><div class="code-block"><div class="code-header"><span class="lang-label">Python</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kn">import</span><span class="w"> </span><span class="nn">torch</span>
<span class="kn">import</span><span class="w"> </span><span class="nn">numpy</span><span class="w"> </span><span class="k">as</span><span class="w"> </span><span class="nn">np</span>
<span class="kn">import</span><span class="w"> </span><span class="nn">torch_npu</span>

<span class="k">if</span> <span class="vm">__name__</span> <span class="o">==</span> <span class="s2">&quot;__main__&quot;</span><span class="p">:</span>
    <span class="n">token_num</span> <span class="o">=</span> <span class="mi">864</span>
    <span class="n">expert_num</span> <span class="o">=</span> <span class="mi">2048</span>
    <span class="n">top_k</span> <span class="o">=</span> <span class="mi">1024</span>

    <span class="c1"># 定义模型model</span>
    <span class="k">class</span><span class="w"> </span><span class="nc">ModelOrigin</span><span class="p">(</span><span class="n">torch</span><span class="o">.</span><span class="n">nn</span><span class="o">.</span><span class="n">Module</span><span class="p">):</span>
        <span class="k">def</span><span class="w"> </span><span class="fm">__init__</span><span class="p">(</span><span class="bp">self</span><span class="p">,</span> <span class="n">top_k</span><span class="p">):</span>
            <span class="nb">super</span><span class="p">()</span><span class="o">.</span><span class="fm">__init__</span><span class="p">()</span>
            <span class="bp">self</span><span class="o">.</span><span class="n">top_k</span> <span class="o">=</span> <span class="n">top_k</span>

        <span class="k">def</span><span class="w"> </span><span class="nf">forward</span><span class="p">(</span><span class="bp">self</span><span class="p">,</span> <span class="n">gating_input</span><span class="p">,</span> <span class="n">smooth_scales</span><span class="p">):</span>
            <span class="n">moe_gating_res</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">npu_moe_gating_top_k_softmax</span><span class="p">(</span><span class="n">gating_input</span><span class="p">,</span> <span class="kc">None</span><span class="p">,</span> <span class="bp">self</span><span class="o">.</span><span class="n">top_k</span><span class="p">)</span>
            <span class="n">dynamic_quant_res</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">npu_dynamic_quant</span><span class="p">(</span>
                <span class="n">moe_gating_res</span><span class="p">[</span><span class="mi">0</span><span class="p">],</span> <span class="n">smooth_scales</span><span class="o">=</span><span class="n">smooth_scales</span>
            <span class="p">)</span>
            <span class="k">return</span> <span class="n">dynamic_quant_res</span><span class="p">,</span> <span class="n">moe_gating_res</span>

    <span class="k">class</span><span class="w"> </span><span class="nc">ModelSuperKernel</span><span class="p">(</span><span class="n">torch</span><span class="o">.</span><span class="n">nn</span><span class="o">.</span><span class="n">Module</span><span class="p">):</span>
        <span class="k">def</span><span class="w"> </span><span class="fm">__init__</span><span class="p">(</span><span class="bp">self</span><span class="p">,</span> <span class="n">top_k</span><span class="p">):</span>
            <span class="nb">super</span><span class="p">()</span><span class="o">.</span><span class="fm">__init__</span><span class="p">()</span>
            <span class="bp">self</span><span class="o">.</span><span class="n">top_k</span> <span class="o">=</span> <span class="n">top_k</span>

        <span class="k">def</span><span class="w"> </span><span class="nf">forward</span><span class="p">(</span><span class="bp">self</span><span class="p">,</span> <span class="n">gating_input</span><span class="p">,</span> <span class="n">smooth_scales</span><span class="p">):</span>
            <span class="c1"># 仅将npu_moe_gating_top_k_softmax融合为SuperKernel，标记为sp1</span>
            <span class="n">torch</span><span class="o">.</span><span class="n">npu</span><span class="o">.</span><span class="n">super_kernel_scope_begin</span><span class="p">(</span><span class="s2">&quot;sp1&quot;</span><span class="p">)</span>
            <span class="n">moe_gating_res</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">npu_moe_gating_top_k_softmax</span><span class="p">(</span><span class="n">gating_input</span><span class="p">,</span> <span class="kc">None</span><span class="p">,</span> <span class="bp">self</span><span class="o">.</span><span class="n">top_k</span><span class="p">)</span>
            <span class="n">torch</span><span class="o">.</span><span class="n">npu</span><span class="o">.</span><span class="n">super_kernel_scope_end</span><span class="p">(</span><span class="s2">&quot;sp1&quot;</span><span class="p">)</span>
            <span class="n">dynamic_quant_res</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">npu_dynamic_quant</span><span class="p">(</span>
                <span class="n">moe_gating_res</span><span class="p">[</span><span class="mi">0</span><span class="p">],</span> <span class="n">smooth_scales</span><span class="o">=</span><span class="n">smooth_scales</span>
            <span class="p">)</span>
            <span class="k">return</span> <span class="n">dynamic_quant_res</span><span class="p">,</span> <span class="n">moe_gating_res</span>

    <span class="n">gating_input</span> <span class="o">=</span> <span class="n">torch</span><span class="o">.</span><span class="n">randn</span><span class="p">((</span><span class="n">token_num</span><span class="p">,</span> <span class="n">expert_num</span><span class="p">),</span> <span class="n">dtype</span><span class="o">=</span><span class="n">torch</span><span class="o">.</span><span class="n">bfloat16</span><span class="p">)</span>
    <span class="n">smooth_scales</span> <span class="o">=</span> <span class="n">torch</span><span class="o">.</span><span class="n">randn</span><span class="p">((</span><span class="n">top_k</span><span class="p">,),</span> <span class="n">dtype</span><span class="o">=</span><span class="n">torch</span><span class="o">.</span><span class="n">bfloat16</span><span class="p">)</span>
    <span class="c1"># 使用图模式后端编译模型</span>
    <span class="n">model_sk</span> <span class="o">=</span> <span class="n">torch</span><span class="o">.</span><span class="n">compile</span><span class="p">(</span>
        <span class="n">ModelSuperKernel</span><span class="p">(</span><span class="n">top_k</span><span class="p">),</span>
        <span class="n">backend</span><span class="o">=</span><span class="s2">&quot;npugraph_ex&quot;</span><span class="p">,</span>
        <span class="n">options</span><span class="o">=</span><span class="p">{</span><span class="s2">&quot;static_kernel_compile&quot;</span><span class="p">:</span> <span class="kc">True</span><span class="p">,</span> <span class="s2">&quot;super_kernel_optimize&quot;</span><span class="p">:</span> <span class="kc">True</span><span class="p">},</span>
        <span class="n">dynamic</span><span class="o">=</span><span class="kc">False</span><span class="p">,</span>
    <span class="p">)</span>
    <span class="nb">print</span><span class="p">(</span><span class="s2">&quot;-------------------- run sk -----------------------------------&quot;</span><span class="p">)</span>
    <span class="n">dynamic_quant_res_sk</span><span class="p">,</span> <span class="n">_</span> <span class="o">=</span> <span class="n">model_sk</span><span class="p">(</span><span class="n">gating_input</span><span class="o">.</span><span class="n">npu</span><span class="p">(),</span> <span class="n">smooth_scales</span><span class="o">.</span><span class="n">npu</span><span class="p">())</span>
    <span class="n">model_no_sk</span> <span class="o">=</span> <span class="n">torch</span><span class="o">.</span><span class="n">compile</span><span class="p">(</span><span class="n">ModelOrigin</span><span class="p">(</span><span class="n">top_k</span><span class="p">),</span> <span class="n">backend</span><span class="o">=</span><span class="s2">&quot;npugraph_ex&quot;</span><span class="p">,</span> <span class="n">dynamic</span><span class="o">=</span><span class="kc">False</span><span class="p">)</span>
    <span class="nb">print</span><span class="p">(</span><span class="s2">&quot;-------------------- run no sk -----------------------------------&quot;</span><span class="p">)</span>
    <span class="n">dynamic_quant_res_origin</span><span class="p">,</span> <span class="n">_</span> <span class="o">=</span> <span class="n">model_no_sk</span><span class="p">(</span><span class="n">gating_input</span><span class="o">.</span><span class="n">npu</span><span class="p">(),</span> <span class="n">smooth_scales</span><span class="o">.</span><span class="n">npu</span><span class="p">())</span>
    <span class="n">res</span> <span class="o">=</span> <span class="n">np</span><span class="o">.</span><span class="n">array_equal</span><span class="p">(</span><span class="n">dynamic_quant_res_origin</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="o">.</span><span class="n">cpu</span><span class="p">()</span><span class="o">.</span><span class="n">numpy</span><span class="p">(),</span> <span class="n">dynamic_quant_res_sk</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="o">.</span><span class="n">cpu</span><span class="p">()</span><span class="o">.</span><span class="n">numpy</span><span class="p">())</span>
    <span class="n">res</span> <span class="o">=</span> <span class="n">res</span> <span class="ow">and</span> <span class="n">np</span><span class="o">.</span><span class="n">array_equal</span><span class="p">(</span><span class="n">dynamic_quant_res_origin</span><span class="p">[</span><span class="mi">1</span><span class="p">]</span><span class="o">.</span><span class="n">cpu</span><span class="p">()</span><span class="o">.</span><span class="n">numpy</span><span class="p">(),</span> <span class="n">dynamic_quant_res_sk</span><span class="p">[</span><span class="mi">1</span><span class="p">]</span><span class="o">.</span><span class="n">cpu</span><span class="p">()</span><span class="o">.</span><span class="n">numpy</span><span class="p">())</span>
    <span class="k">if</span> <span class="n">res</span><span class="p">:</span>
        <span class="nb">print</span><span class="p">(</span><span class="s2">&quot;Precision ====== Success!!!&quot;</span><span class="p">)</span>
    <span class="k">else</span><span class="p">:</span>
        <span class="nb">print</span><span class="p">(</span><span class="s2">&quot;Precision ====== Failed.&quot;</span><span class="p">)</span>
</code></pre></div><h3 id="关键点说明">关键点说明<a class="header-anchor" href="#关键点说明">​</a></h3><ul><li><p><code>torch.npu.super_kernel_scope_begin(scope_name)</code>/<code>torch.npu.super_kernel_scope_end(scope_name)</code>：成对出现，配对的<code>scope_name</code>必须一致。相同的<code>scope_name</code>代表相同的融合范围，由用户控制。若传入<code>None</code>，则该范围内的算子不进行SuperKernel融合。</p></li><li><p><code>torch.compile(model, backend=&quot;npugraph_ex&quot;, options={...}, dynamic=False)</code>：通过npugraph_ex后端下发图，仅支持静态图（<code>dynamic=False</code>）。<code>super_kernel_optimize=True</code>是开启SuperKernel融合优化的必要开关；其他融合优化与调试参数（如<code>super_kernel_optimize_options</code>、<code>super_kernel_debug_options</code>等）请参见<a href="https://www.hiascend.com/document/detail/zh/Pytorch/latest/devguide/TorchAir/docs/zh/npugraph_ex/advanced/superkernel.md">SuperKernel功能</a>。</p></li><li><p><strong>满核场景验证</strong>：SuperKernel启动核数由其内部子算子的最大启动核数决定。在实际整网场景中，融合的算子较多，SuperKernel通常会启动满核（如24 Cube + 48 Vector）；但单算子验证时，单个算子的启动核数可能远未达到满核，导致SuperKernel也不会启动满核，从而无法充分验证算子适配说明中与核数相关的约束（如全核同步、硬同步等），为此，npugraph_ex后端可通过<code>super_kernel_debug_options</code>中的<code>debug_per_op_max_core_num</code>选项开启单算子满核验证模式。开启后，融合范围内的每个算子会独立成为一个SuperKernel，并以设备最大核数启动运行（Cube和Vector均启动最大核数）。示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Python</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># npugraph_ex后端：开启单算子满核验证模式</span>
<span class="n">model_sk</span> <span class="o">=</span> <span class="n">torch</span><span class="o">.</span><span class="n">compile</span><span class="p">(</span>
    <span class="n">ModelSuperKernel</span><span class="p">(),</span>
    <span class="n">backend</span><span class="o">=</span><span class="s2">&quot;npugraph_ex&quot;</span><span class="p">,</span>
    <span class="n">options</span><span class="o">=</span><span class="p">{</span>
        <span class="s2">&quot;static_kernel_compile&quot;</span><span class="p">:</span> <span class="kc">True</span><span class="p">,</span>
        <span class="s2">&quot;super_kernel_optimize&quot;</span><span class="p">:</span> <span class="kc">True</span><span class="p">,</span>
        <span class="s2">&quot;super_kernel_debug_options&quot;</span><span class="p">:</span> <span class="p">{</span><span class="s2">&quot;debug_per_op_max_core_num&quot;</span><span class="p">:</span> <span class="mi">1</span><span class="p">},</span>
    <span class="p">},</span>
    <span class="n">dynamic</span><span class="o">=</span><span class="kc">False</span><span class="p">,</span>
<span class="p">)</span>
</code></pre></div><p><code>debug_per_op_max_core_num</code>的详细说明请参见<a href="https://www.hiascend.com/document/detail/zh/Pytorch/latest/devguide/TorchAir/docs/zh/npugraph_ex/advanced/superkernel.md">SuperKernel功能</a>。</p></li></ul><h2 id="GE图模式验证样例">GE图模式验证样例<a class="header-anchor" href="#GE图模式验证样例">​</a></h2><p>GE图模式通过<code>torchair.scope.super_kernel</code>作用域标定融合范围，编译后端使用<code>torchair.get_npu_backend()</code>返回的<code>npu_backend</code>。使用时需通过<code>with</code>语句块将待融合算子包裹在<code>torchair.scope.super_kernel(scope, options)</code>范围内。</p><h3 id="示例代码-1">示例代码<a class="header-anchor" href="#示例代码-1">​</a></h3><p>以下示例以<code>torch_npu.npu_moe_gating_top_k_softmax</code>为例，演示在GE图模式下的SuperKernel单算子验证：</p><div class="code-block"><div class="code-header"><span class="lang-label">Python</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kn">import</span><span class="w"> </span><span class="nn">torch</span>
<span class="kn">import</span><span class="w"> </span><span class="nn">numpy</span><span class="w"> </span><span class="k">as</span><span class="w"> </span><span class="nn">np</span>
<span class="kn">import</span><span class="w"> </span><span class="nn">torch_npu</span>
<span class="kn">import</span><span class="w"> </span><span class="nn">torchair</span>
<span class="kn">from</span><span class="w"> </span><span class="nn">torchair.configs.compiler_config</span><span class="w"> </span><span class="kn">import</span> <span class="n">CompilerConfig</span>

<span class="k">if</span> <span class="vm">__name__</span> <span class="o">==</span> <span class="s2">&quot;__main__&quot;</span><span class="p">:</span>
    <span class="n">config</span> <span class="o">=</span> <span class="n">CompilerConfig</span><span class="p">()</span>
    <span class="n">config</span><span class="o">.</span><span class="n">debug</span><span class="o">.</span><span class="n">graph_dump</span><span class="o">.</span><span class="n">type</span> <span class="o">=</span> <span class="s2">&quot;pbtxt&quot;</span>
    <span class="n">npu_backend</span> <span class="o">=</span> <span class="n">torchair</span><span class="o">.</span><span class="n">get_npu_backend</span><span class="p">(</span><span class="n">compiler_config</span><span class="o">=</span><span class="n">config</span><span class="p">)</span>

    <span class="c1"># 定义模型model</span>
    <span class="k">class</span><span class="w"> </span><span class="nc">ModelOrigin</span><span class="p">(</span><span class="n">torch</span><span class="o">.</span><span class="n">nn</span><span class="o">.</span><span class="n">Module</span><span class="p">):</span>
        <span class="k">def</span><span class="w"> </span><span class="fm">__init__</span><span class="p">(</span><span class="bp">self</span><span class="p">,</span> <span class="n">top_k</span><span class="p">):</span>
            <span class="nb">super</span><span class="p">()</span><span class="o">.</span><span class="fm">__init__</span><span class="p">()</span>
            <span class="bp">self</span><span class="o">.</span><span class="n">top_k</span> <span class="o">=</span> <span class="n">top_k</span>

        <span class="k">def</span><span class="w"> </span><span class="nf">forward</span><span class="p">(</span><span class="bp">self</span><span class="p">,</span> <span class="n">gating_input</span><span class="p">,</span> <span class="n">smooth_scales</span><span class="p">):</span>
            <span class="n">moe_gating_res</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">npu_moe_gating_top_k_softmax</span><span class="p">(</span><span class="n">gating_input</span><span class="p">,</span> <span class="kc">None</span><span class="p">,</span> <span class="bp">self</span><span class="o">.</span><span class="n">top_k</span><span class="p">)</span>
            <span class="n">dynamic_quant_res</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">npu_dynamic_quant</span><span class="p">(</span>
                <span class="n">moe_gating_res</span><span class="p">[</span><span class="mi">0</span><span class="p">],</span> <span class="n">smooth_scales</span><span class="o">=</span><span class="n">smooth_scales</span>
            <span class="p">)</span>
            <span class="k">return</span> <span class="n">dynamic_quant_res</span><span class="p">,</span> <span class="n">moe_gating_res</span>

    <span class="k">class</span><span class="w"> </span><span class="nc">ModelSuperKernel</span><span class="p">(</span><span class="n">torch</span><span class="o">.</span><span class="n">nn</span><span class="o">.</span><span class="n">Module</span><span class="p">):</span>
        <span class="k">def</span><span class="w"> </span><span class="fm">__init__</span><span class="p">(</span><span class="bp">self</span><span class="p">,</span> <span class="n">top_k</span><span class="p">):</span>
            <span class="nb">super</span><span class="p">()</span><span class="o">.</span><span class="fm">__init__</span><span class="p">()</span>
            <span class="bp">self</span><span class="o">.</span><span class="n">top_k</span> <span class="o">=</span> <span class="n">top_k</span>

        <span class="k">def</span><span class="w"> </span><span class="nf">forward</span><span class="p">(</span><span class="bp">self</span><span class="p">,</span> <span class="n">gating_input</span><span class="p">,</span> <span class="n">smooth_scales</span><span class="p">):</span>
            <span class="c1"># 仅将npu_moe_gating_top_k_softmax融合为SuperKernel，标记为sp1</span>
            <span class="k">with</span> <span class="n">torchair</span><span class="o">.</span><span class="n">scope</span><span class="o">.</span><span class="n">super_kernel</span><span class="p">(</span><span class="s2">&quot;sp1&quot;</span><span class="p">,</span> <span class="s2">&quot;&quot;</span><span class="p">):</span>
                <span class="n">moe_gating_res</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">npu_moe_gating_top_k_softmax</span><span class="p">(</span><span class="n">gating_input</span><span class="p">,</span> <span class="kc">None</span><span class="p">,</span> <span class="bp">self</span><span class="o">.</span><span class="n">top_k</span><span class="p">)</span>
            <span class="n">dynamic_quant_res</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">npu_dynamic_quant</span><span class="p">(</span>
                <span class="n">moe_gating_res</span><span class="p">[</span><span class="mi">0</span><span class="p">],</span> <span class="n">smooth_scales</span><span class="o">=</span><span class="n">smooth_scales</span>
            <span class="p">)</span>
            <span class="k">return</span> <span class="n">dynamic_quant_res</span><span class="p">,</span> <span class="n">moe_gating_res</span>

    <span class="n">token_num</span> <span class="o">=</span> <span class="mi">864</span>
    <span class="n">expert_num</span> <span class="o">=</span> <span class="mi">2048</span>
    <span class="n">top_k</span> <span class="o">=</span> <span class="mi">1024</span>
    <span class="n">gating_input</span> <span class="o">=</span> <span class="n">torch</span><span class="o">.</span><span class="n">randn</span><span class="p">((</span><span class="n">token_num</span><span class="p">,</span> <span class="n">expert_num</span><span class="p">),</span> <span class="n">dtype</span><span class="o">=</span><span class="n">torch</span><span class="o">.</span><span class="n">bfloat16</span><span class="p">)</span>
    <span class="n">smooth_scales</span> <span class="o">=</span> <span class="n">torch</span><span class="o">.</span><span class="n">randn</span><span class="p">((</span><span class="n">top_k</span><span class="p">,),</span> <span class="n">dtype</span><span class="o">=</span><span class="n">torch</span><span class="o">.</span><span class="n">bfloat16</span><span class="p">)</span>
    <span class="c1"># 使用图模式后端编译模型</span>
    <span class="n">model_no_sk</span> <span class="o">=</span> <span class="n">torch</span><span class="o">.</span><span class="n">compile</span><span class="p">(</span><span class="n">ModelOrigin</span><span class="p">(</span><span class="n">top_k</span><span class="p">),</span> <span class="n">backend</span><span class="o">=</span><span class="n">npu_backend</span><span class="p">,</span> <span class="n">dynamic</span><span class="o">=</span><span class="kc">False</span><span class="p">)</span>
    <span class="nb">print</span><span class="p">(</span><span class="s2">&quot;-------------------- run no sk -----------------------------------&quot;</span><span class="p">)</span>
    <span class="n">dynamic_quant_res_origin</span><span class="p">,</span> <span class="n">_</span> <span class="o">=</span> <span class="n">model_no_sk</span><span class="p">(</span><span class="n">gating_input</span><span class="o">.</span><span class="n">npu</span><span class="p">(),</span> <span class="n">smooth_scales</span><span class="o">.</span><span class="n">npu</span><span class="p">())</span>
    <span class="n">model_sk</span> <span class="o">=</span> <span class="n">torch</span><span class="o">.</span><span class="n">compile</span><span class="p">(</span><span class="n">ModelSuperKernel</span><span class="p">(</span><span class="n">top_k</span><span class="p">),</span> <span class="n">backend</span><span class="o">=</span><span class="n">npu_backend</span><span class="p">,</span> <span class="n">dynamic</span><span class="o">=</span><span class="kc">False</span><span class="p">)</span>
    <span class="nb">print</span><span class="p">(</span><span class="s2">&quot;-------------------- run sk -----------------------------------&quot;</span><span class="p">)</span>
    <span class="n">dynamic_quant_res_sk</span><span class="p">,</span> <span class="n">_</span> <span class="o">=</span> <span class="n">model_sk</span><span class="p">(</span><span class="n">gating_input</span><span class="o">.</span><span class="n">npu</span><span class="p">(),</span> <span class="n">smooth_scales</span><span class="o">.</span><span class="n">npu</span><span class="p">())</span>
    <span class="n">res</span> <span class="o">=</span> <span class="n">np</span><span class="o">.</span><span class="n">array_equal</span><span class="p">(</span><span class="n">dynamic_quant_res_origin</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="o">.</span><span class="n">cpu</span><span class="p">()</span><span class="o">.</span><span class="n">numpy</span><span class="p">(),</span> <span class="n">dynamic_quant_res_sk</span><span class="p">[</span><span class="mi">0</span><span class="p">]</span><span class="o">.</span><span class="n">cpu</span><span class="p">()</span><span class="o">.</span><span class="n">numpy</span><span class="p">())</span>
    <span class="n">res</span> <span class="o">=</span> <span class="n">res</span> <span class="ow">and</span> <span class="n">np</span><span class="o">.</span><span class="n">array_equal</span><span class="p">(</span><span class="n">dynamic_quant_res_origin</span><span class="p">[</span><span class="mi">1</span><span class="p">]</span><span class="o">.</span><span class="n">cpu</span><span class="p">()</span><span class="o">.</span><span class="n">numpy</span><span class="p">(),</span> <span class="n">dynamic_quant_res_sk</span><span class="p">[</span><span class="mi">1</span><span class="p">]</span><span class="o">.</span><span class="n">cpu</span><span class="p">()</span><span class="o">.</span><span class="n">numpy</span><span class="p">())</span>
    <span class="k">if</span> <span class="n">res</span><span class="p">:</span>
        <span class="nb">print</span><span class="p">(</span><span class="s2">&quot;Precision ====== Success!!!&quot;</span><span class="p">)</span>
    <span class="k">else</span><span class="p">:</span>
        <span class="nb">print</span><span class="p">(</span><span class="s2">&quot;Precision ====== Failed.&quot;</span><span class="p">)</span>
</code></pre></div><h3 id="关键点说明-1">关键点说明<a class="header-anchor" href="#关键点说明-1">​</a></h3><ul><li><p><code>torchair.scope.super_kernel(scope, options)</code>：用<code>with</code>语句块标定SuperKernel融合范围。<code>scope</code>表示该范围内算子被融合的SuperKernel名称，相同的scope代表相同的范围，由用户控制。若传入None，表示该范围内的算子不进行SuperKernel融合。<code>options</code>表示融合SuperKernel的编译选项，格式形如<code>&quot;&lt;option1&gt;=&lt;value1&gt;:&lt;option2&gt;=&lt;value2&gt;&quot;</code>，多个选项用英文冒号分割。编译选项说明请参见<a href="https://www.hiascend.com/document/detail/zh/Pytorch/latest/devguide/TorchAir/docs/zh/ascend_ir/features/advanced/super_kernel_scope.md">图内标定SuperKernel范围</a>。</p></li><li><p><code>torch.compile(model, backend=npu_backend, dynamic=False)</code>：通过GE图模式下发图，仅支持静态图（<code>dynamic=False</code>）。</p></li><li><p><strong>满核场景验证</strong>：SuperKernel启动核数由其内部子算子的最大启动核数决定。在实际整网场景中，融合的算子较多，SuperKernel通常会启动满核（如24 Cube + 48 Vector）；但单算子验证时，单个算子的启动核数可能远未达到满核，导致SuperKernel也不会启动满核，从而无法充分验证<a href="operator_adaptation.html">算子适配说明</a>中与核数相关的约束（如全核同步、硬同步等）。为此，可通过<code>options</code>中的<code>debug-aic-num</code>和<code>debug-aiv-num</code>选项强制指定SuperKernel的启动核数，模拟满核场景进行验证。例如，强制SuperKernel以24 Cube + 48 Vector启动：</p><div class="code-block"><div class="code-header"><span class="lang-label">Python</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># 强制SuperKernel以满核启动，模拟真实整网场景</span>
<span class="k">with</span> <span class="n">torchair</span><span class="o">.</span><span class="n">scope</span><span class="o">.</span><span class="n">super_kernel</span><span class="p">(</span><span class="s2">&quot;sk1&quot;</span><span class="p">,</span> <span class="s2">&quot;debug-aic-num=24:debug-aiv-num=48&quot;</span><span class="p">):</span>
    <span class="n">y</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">my_custom_op</span><span class="p">(</span><span class="n">x</span><span class="p">)</span>
</code></pre></div><p><code>debug-aic-num</code>和<code>debug-aiv-num</code>的详细说明请参见<a href="https://www.hiascend.com/document/detail/zh/Pytorch/latest/devguide/TorchAir/docs/zh/ascend_ir/features/advanced/super_kernel_scope.md">图内标定SuperKernel范围</a>。</p></li></ul><h2 id="多算子融合验证">多算子融合验证<a class="header-anchor" href="#多算子融合验证">​</a></h2><p>如需验证待验证算子与其他Ascend C算子的融合效果，可以将多个算子一起放入SuperKernel范围内。例如：</p><ul><li>将待验证算子与另一个已知支持SuperKernel的Ascend C算子一起放入scope内。</li><li>或者在scope内连续调用待验证算子两次或多次（输入可以构造为前后串联）。</li></ul><p>例如：</p><div class="code-block"><div class="code-header"><span class="lang-label">Python</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># npugraph_ex后端：将待验证算子与其他Ascend C算子一起融合</span>
<span class="n">torch</span><span class="o">.</span><span class="n">npu</span><span class="o">.</span><span class="n">super_kernel_scope_begin</span><span class="p">(</span><span class="s2">&quot;sk1&quot;</span><span class="p">)</span>
<span class="n">y1</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">my_custom_op</span><span class="p">(</span><span class="n">x</span><span class="p">)</span>
<span class="n">y2</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">npu_dequant_swiglu_quant</span><span class="p">(</span><span class="n">y1</span><span class="p">,</span> <span class="n">weight_scale</span><span class="o">=</span><span class="n">weight_scale</span><span class="p">)</span>
<span class="n">torch</span><span class="o">.</span><span class="n">npu</span><span class="o">.</span><span class="n">super_kernel_scope_end</span><span class="p">(</span><span class="s2">&quot;sk1&quot;</span><span class="p">)</span>

<span class="c1"># GE图模式：将待验证算子与其他Ascend C算子一起融合</span>
<span class="k">with</span> <span class="n">torchair</span><span class="o">.</span><span class="n">scope</span><span class="o">.</span><span class="n">super_kernel</span><span class="p">(</span><span class="s2">&quot;sk1&quot;</span><span class="p">,</span> <span class="s2">&quot;&quot;</span><span class="p">):</span>
    <span class="n">y1</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">my_custom_op</span><span class="p">(</span><span class="n">x</span><span class="p">)</span>
    <span class="n">y2</span> <span class="o">=</span> <span class="n">torch_npu</span><span class="o">.</span><span class="n">npu_dequant_swiglu_quant</span><span class="p">(</span><span class="n">y1</span><span class="p">,</span> <span class="n">weight_scale</span><span class="o">=</span><span class="n">weight_scale</span><span class="p">)</span>
</code></pre></div></article></div>`,1)])])}const h=a(l,[["render",e]]);export{d as __pageData,h as default};
